int perlin_floor_to_int_n3(float a) {
	return (a >= 0.0) ? int(a) : int(a) - 1;
}

float perlin_fade_n3(float t) {
	return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float perlin_lerp_n3(float t, float a, float b) {
	return a + t * (b - a);
}

float perlin_grad_n3(int hash, float x, float y, float z) {
	int h = hash & 15;
	float u = (h < 8) ? x : y;
	float v = (h < 4) ? y : ((h == 12 || h == 14) ? x : z);
	return ((h & 1) == 0 ? u : -u) + ((h & 2) == 0 ? v : -v);
}

const int perlin_p_n3[256] = int[256](151, 160, 137, 91, 90, 15, 131, 13, 201, 95, 96, 53, 194, 233, 7, 225, 140, 36, 103, 30, 69, 142, 8, 99, 37, 240, 21, 10, 23, 190, 6, 148, 247, 120, 234, 75, 0, 26, 197, 62, 94, 252, 219, 203, 117, 35, 11, 32, 57, 177, 33, 88, 237, 149, 56, 87, 174, 20, 125, 136, 171, 168, 68, 175, 74, 165, 71, 134, 139, 48, 27, 166, 77, 146, 158, 231, 83, 111, 229, 122, 60, 211, 133, 230, 220, 105, 92, 41, 55, 46, 245, 40, 244, 102, 143, 54, 65, 25, 63, 161, 1, 216, 80, 73, 209, 76, 132, 187, 208, 89, 18, 169, 200, 196, 135, 130, 116, 188, 159, 86, 164, 100, 109, 198, 173, 186, 3, 64, 52, 217, 226, 250, 124, 123, 5, 202, 38, 147, 118, 126, 255, 82, 85, 212, 207, 206, 59, 227, 47, 16, 58, 17, 182, 189, 28, 42, 223, 183, 170, 213, 119, 248, 152, 2, 44, 154, 163, 70, 221, 153, 101, 155, 167, 43, 172, 9, 129, 22, 39, 253, 19, 98, 108, 110, 79, 113, 224, 232, 178, 185, 112, 104, 218, 246, 97, 228, 251, 34, 242, 193, 238, 210, 144, 12, 191, 179, 162, 241, 81, 51, 145, 235, 249, 14, 239, 107, 49, 192, 214, 31, 181, 199, 106, 157, 184, 84, 204, 176, 115, 121, 50, 45, 127, 4, 150, 254, 138, 236, 205, 93, 222, 114, 67, 29, 24, 72, 243, 141, 128, 195, 78, 66, 215, 61, 156, 180);

int perlin_perm_n3(int idx) {
	return perlin_p_n3[idx & 255];
}

float perlin_sample3d_n3(vec3 pos, float scale) {
	vec3 xyz = pos * scale;
	int X = perlin_floor_to_int_n3(xyz.x);
	int Y = perlin_floor_to_int_n3(xyz.y);
	int Z = perlin_floor_to_int_n3(xyz.z);
	xyz -= vec3(float(X), float(Y), float(Z));
	X &= 255;
	Y &= 255;
	Z &= 255;

	float u = perlin_fade_n3(xyz.x);
	float v = perlin_fade_n3(xyz.y);
	float w = perlin_fade_n3(xyz.z);

	int A = perlin_perm_n3(X) + Y;
	int AA = perlin_perm_n3(A) + Z;
	int AB = perlin_perm_n3(A + 1) + Z;
	int B = perlin_perm_n3(X + 1) + Y;
	int BA = perlin_perm_n3(B) + Z;
	int BB = perlin_perm_n3(B + 1) + Z;

	return perlin_lerp_n3(w, perlin_lerp_n3(v, perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AA), xyz.x, xyz.y, xyz.z), perlin_grad_n3(perlin_perm_n3(BA), xyz.x - 1.0, xyz.y, xyz.z)), perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AB), xyz.x, xyz.y - 1.0, xyz.z), perlin_grad_n3(perlin_perm_n3(BB), xyz.x - 1.0, xyz.y - 1.0, xyz.z))), perlin_lerp_n3(v, perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AA + 1), xyz.x, xyz.y, xyz.z - 1.0), perlin_grad_n3(perlin_perm_n3(BA + 1), xyz.x - 1.0, xyz.y, xyz.z - 1.0)), perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AB + 1), xyz.x, xyz.y - 1.0, xyz.z - 1.0), perlin_grad_n3(perlin_perm_n3(BB + 1), xyz.x - 1.0, xyz.y - 1.0, xyz.z - 1.0))));
}

float perlin_sample3d_periodic_n3(vec3 pos, int period_x, int period_y, int period_z) {
	vec3 xyz = pos;
	int X = perlin_floor_to_int_n3(xyz.x);
	int Y = perlin_floor_to_int_n3(xyz.y);
	int Z = perlin_floor_to_int_n3(xyz.z);
	xyz -= vec3(float(X), float(Y), float(Z));
	X &= 255;
	Y &= 255;
	Z &= 255;

	int Ix = X % period_x;
	int Iy = Y % period_y;
	int Iz = Z % period_z;
	int Jx = (Ix + 1) % period_x;
	int Jy = (Iy + 1) % period_y;
	int Jz = (Iz + 1) % period_z;

	float u = perlin_fade_n3(xyz.x);
	float v = perlin_fade_n3(xyz.y);
	float w = perlin_fade_n3(xyz.z);

	int A = perlin_perm_n3(Ix);
	int AA = perlin_perm_n3(A + Iy);
	int AB = perlin_perm_n3(A + Jy);
	int B = perlin_perm_n3(Jx);
	int BA = perlin_perm_n3(B + Iy);
	int BB = perlin_perm_n3(B + Jy);

	return perlin_lerp_n3(w, perlin_lerp_n3(v, perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AA + Iz), xyz.x, xyz.y, xyz.z), perlin_grad_n3(perlin_perm_n3(BA + Iz), xyz.x - 1.0, xyz.y, xyz.z)), perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AB + Iz), xyz.x, xyz.y - 1.0, xyz.z), perlin_grad_n3(perlin_perm_n3(BB + Iz), xyz.x - 1.0, xyz.y - 1.0, xyz.z))), perlin_lerp_n3(v, perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AA + Jz), xyz.x, xyz.y, xyz.z - 1.0), perlin_grad_n3(perlin_perm_n3(BA + Jz), xyz.x - 1.0, xyz.y, xyz.z - 1.0)), perlin_lerp_n3(u, perlin_grad_n3(perlin_perm_n3(AB + Jz), xyz.x, xyz.y - 1.0, xyz.z - 1.0), perlin_grad_n3(perlin_perm_n3(BB + Jz), xyz.x - 1.0, xyz.y - 1.0, xyz.z - 1.0))));
}

in vec2 FragCoord;
uniform float uTime;
out vec4 FragColor;

void main() {
// Input:1
	vec2 var_from_n1_p0 = FragCoord;


// PerlinNoise:3
	// Perlin Noise
	float perlin_val_n3 = 0.0;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 1.000000, var_from_n1_p0.y * 1.000000, 0.0), 1, 1, 256) * 1.000000;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 2.000000, var_from_n1_p0.y * 2.000000, 0.0), 2, 2, 256) * 0.500000;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 4.000000, var_from_n1_p0.y * 4.000000, 0.0), 4, 4, 256) * 0.250000;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 8.000000, var_from_n1_p0.y * 8.000000, 0.0), 8, 8, 256) * 0.125000;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 16.000000, var_from_n1_p0.y * 16.000000, 0.0), 16, 16, 256) * 0.062500;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 32.000000, var_from_n1_p0.y * 32.000000, 0.0), 32, 32, 256) * 0.031250;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 64.000000, var_from_n1_p0.y * 64.000000, 0.0), 64, 64, 256) * 0.015625;
	perlin_val_n3 += perlin_sample3d_periodic_n3(vec3(var_from_n1_p0.x * 128.000000, var_from_n1_p0.y * 128.000000, 0.0), 128, 128, 256) * 0.007812;
	perlin_val_n3 = perlin_val_n3 * 0.5 + 0.5;
	perlin_val_n3 *= 1.000000;
	perlin_val_n3 = clamp(perlin_val_n3, 0.0, 1.0);
	vec4 perlin_out_n3 = vec4(0.000000, 0.000000, 0.000000, 255.000000) / 255.000000;
	if (perlin_val_n3 >= 1.000000) {
		perlin_out_n3 = vec4(255.000000, 255.000000, 255.000000, 255.000000) / 255.000000;
	} else if (perlin_val_n3 > 0.000000) {
		if (perlin_val_n3 < 1.000000) {
			float perlin_n3_interp_0 = (perlin_val_n3 - 0.000000) / 1.000000;
			perlin_out_n3 = mix(vec4(0.000000, 0.000000, 0.000000, 255.000000) / 255.000000, vec4(255.000000, 255.000000, 255.000000, 255.000000) / 255.000000, perlin_n3_interp_0);
		}
	}
	vec4 var_from_n3_p0 = perlin_out_n3;


// Input:2
	float var_from_n2_p0 = uTime;


// FloatFunc:4
	float var_from_n4_p0 = sin(var_from_n2_p0);


// FloatConstant:5
	float var_from_n5_p0 = 2.000000;


// FloatOp:6
	float var_from_n6_p0 = var_from_n4_p0 / var_from_n5_p0;


// FloatOp:7
	float var_from_n7_p0 = var_from_n3_p0.x - var_from_n6_p0;


// FloatFunc:8
	float var_from_n8_p0 = round(var_from_n7_p0);


// Output:0
	FragColor = vec4(var_from_n8_p0);


}
